import java.util.*;
import java.util.regex.*;

public class LineMatcher {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the text (end with a blank line): ");

        StringBuilder textBuilder = new StringBuilder();
        while (scanner.hasNextLine()) {
            String line = scanner.nextLine();
            if (line.isBlank()) break;
            textBuilder.append(line).append("\n");
        }
        String text = textBuilder.toString();

        System.out.print("Enter the regular expression: ");
        String patternInput = scanner.nextLine();

        System.out.println();

        try {
            Pattern pattern = Pattern.compile(patternInput);

            if (text.isEmpty()) {
                System.out.println("Input text is empty. No lines to match.");
                return;
            }

            String[] lines = text.split("\n", -1);
            List<Integer> matches = new ArrayList<>();

            for (int i = 0; i < lines.length; i++) {
                if (pattern.matcher(lines[i]).find()) {
                    matches.add(i + 1);
                }
            }

            System.out.println("Match results, as entered:");
            System.out.println("Lines containing the pattern: " + matches.size());
            System.out.println("Line numbers: " + matches);
            if (matches.size() <= 10) {
                for (int index : matches) {
                    System.out.println("Line " + index + ": " + lines[index - 1]);
                }
            } else {
                System.out.println("First ten lines:");
                for (int index : matches.subList(0, 10)) {
                    System.out.println("Line " + index + ": " + lines[index - 1]);
                }
            }

        } catch (IllegalArgumentException e) {
            System.out.println("The input text is empty.");
        } catch (PatternSyntaxException e) {
            System.out.println("The regular expression is invalid: " + e.getMessage());
        }
    }
}
```

